<script setup lang="ts">
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import { useBranding } from '@/composables/useBranding'
import { formatActiveDate } from '@/utils/localization'
import type { AcademyAttendanceRow } from '@/api/academyAttendance'
const props = defineProps<{ title: string; month: string; dates: string[]; rows: AcademyAttendanceRow[] }>()
const { t, locale } = useI18n(); const { logoUrl, originalCompanyName } = useBranding()
const dayNumbers = computed(() => props.dates.map(date => Number(date.slice(8, 10))))
const statuses = ['present', 'absent', 'leave']
const monthLabel = computed(() => { const [year, month] = props.month.split('-').map(Number); return new Intl.DateTimeFormat(locale.value, { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(new Date(Date.UTC(year, month - 1, 1))) })
</script>
<template><div class="academy-attendance-document" :dir="$i18n.locale === 'en' ? 'ltr' : 'rtl'"><div class="print-container"><header><div class="d-flex align-center ga-3"><img v-if="logoUrl" :src="logoUrl" :alt="originalCompanyName"><div><strong>{{ originalCompanyName }}</strong><div>{{ t('academy.attendance.printSubtitle') }}</div></div></div><div class="text-end"><h2>{{ title }}</h2><div>{{ monthLabel }}</div></div></header><table><thead><tr><th class="name">{{ t('academy.fields.student') }}</th><th v-for="day in dayNumbers" :key="day">{{ day }}</th><th>{{ t('academy.attendance.totalRecorded') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.enrollment_id"><td class="name">{{ row.name }}<small>{{ row.student_number }}</small></td><td v-for="date in dates" :key="date"><span v-if="row.attendance[date]" :class="`status-${row.attendance[date].status}`">{{ t(`academy.attendance.status.${row.attendance[date].status}`).charAt(0) }}</span></td><td>{{ Object.keys(row.attendance).filter(date => dates.includes(date)).length }}</td></tr></tbody></table><footer><div><strong>{{ t('academy.attendance.legend') }}:</strong> <span v-for="status in statuses" :key="status" class="me-3">{{ t(`academy.attendance.status.${status}`) }}</span></div><span>{{ formatActiveDate(new Date()) }}</span></footer></div></div></template>
<style scoped>.academy-attendance-document{color:#111;background:#fff}.print-container{inline-size:100%}header{display:flex;align-items:center;justify-content:space-between;border-block-end:2px solid #80027f;padding-block-end:8px;margin-block-end:12px}header img{max-inline-size:38mm;max-block-size:14mm;object-fit:contain}h2{margin:0;font-size:16pt}table{inline-size:100%;border-collapse:collapse;table-layout:fixed;font-size:7pt}th,td{border:1px solid #cbd5e1;padding:3px;text-align:center;overflow:hidden}th{background:#f1f5f9;font-weight:700}.name{inline-size:34mm;text-align:start}.name small{display:block;color:#64748b}.status-present{color:#047857;font-weight:800}.status-absent{color:#b91c1c;font-weight:800}.status-leave{color:#1d4ed8;font-weight:800}footer{display:flex;justify-content:space-between;margin-block-start:8px;font-size:8pt;color:#475569}</style>
